```c++
#include <iostream>
네임스페이스 std를 사용합니다;

void orderArray(int arr[], int n) {
    int i, j
    for (i = 0; i < n-1; i++) {
        for (j = 0; j < n-i-1; j++) {
            if (arr[j] > arr[j+1]) {
                // 스왑
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
            }
        }
    }
}

int main()
{
    int myArray[] = {64, 34, 25, 12, 22, 11, 90};
    int n = sizeof(myArray)/sizeof(myArray[0]);
    orderArray(myArray, n);
    cout << "정렬된 배열입니다: ";
    for (int i=0; i < n; i++)
        cout << myArray[i] << " ";
    cout << endl;
    반환 0;
}
```
