다음은 배열의 요소를 반전시키는 C++ 프로그램입니다:

```c++
#include <iostream>

네임스페이스 std를 사용합니다;

void reverseArray(int arr[], int n) {
    // 시작과 끝 인덱스 초기화
    int start = 0;
    int end = n-1;
    // 배열의 절반을 반복합니다.
    while (start < end) {
        // 시작과 끝의 값을 바꿉니다.
        int temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        // 증가 시작과 감소 끝
        start++;
        end--;
    }
}

void printArray(int arr[], int n) {
    // 배열을 반복하고 값을 출력합니다.
    for (int i = 0; i < n; i++)
        cout << arr[i] << " ";
    cout << endl;
}

int main() {
    int arr[] = {1, 2, 3, 4, 5, 6};
    int n = sizeof(arr)/sizeof(arr[0]);

    cout << "원래 배열: ";
    printArray(arr, n);

    // 배열 반전
    reverseArray(arr, n);

    cout << "반전된 배열입니다: ";
    printArray(arr, n);

    반환 0;
}
```

