'''자바스크립트
function reverseArray(arr, startIndex, endIndex) {{
  // startIndex와 endIndex가 유효한지 확인합니다.
  if (startIndex < 0 || endIndex > arr.length - 1 || startIndex >= endIndex) {
    return;
  }

  // 지정된 범위의 요소를 반전시킵니다.
  while(startIndex < endIndex) {
    let temp = arr[startIndex];
    arr[startIndex] = arr[endIndex];
    arr[endIndex] = temp;
    startIndex++;
    endIndex--;
  }

  반환 배열;
}

let arr = [1, 2, 3, 4, 5, 6];
let startIndex = 1;
let endIndex = 4;
reverseArray(arr, startIndex, endIndex); // [1, 5, 4, 3, 2, 6]
```
이 함수는 배열 `arr`, 시작 인덱스 `startIndex`, 끝 인덱스 `endIndex`를 입력으로 받습니다. 먼저 시작 인덱스와 끝 인덱스가 배열의 범위 내에 있는지, 시작 인덱스가 끝 인덱스보다 크거나 같지 않은지 확인합니다. 이러한 조건이 충족되지 않으면 배열을 변경하지 않고 함수를 반환합니다.

