```java
public class MyDataStructure {
    private int maxSize; // 데이터 구조체의 최대 크기
    private int[] data; // 데이터를 저장할 배열
    private int top; // 데이터 구조체의 상단

    public DataStructure(int size) {
      maxSize = size;
      data = new int[maxSize];
      top = 0;
    }

    // 데이터 구조에 요소를 추가하는 메서드
    public void push(int value) {
      if (!isFull()) {
        data[top++] = value;
      } else {
        // 전체 데이터 구조에 대한 오류 처리
        System.out.println("데이터 구조가 꽉 찼습니다.");
      }
    }

    // 데이터 구조에서 요소를 제거하는 메서드
    public int pop() {
      if (!isEmpty()) {
        return data[--top];
      } else {
        // 빈 데이터 구조에 대한 오류 처리
        System.out.println("데이터 구조가 비어 있습니다.");
        반환 -1;
      }
    }

    // 데이터 구조가 비어 있는지 확인하는 메서드
    public boolean isEmpty() {
      return top == 0;
    }

    // 데이터 구조가 가득 찼는지 확인하는 메서드
    public boolean isFull() {
      return top == maxSize;
    }

    // 데이터 구조체의 크기를 반환하는 메서드
    public int size() {
      return top;
    }
}
```

